-- Synthetic owner mileage QA; isolated in the disposable fixture transaction.
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select pg_temp.assert_true((public.record_mileage_trip('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000001','2026-10-15','Synthetic supplier trip','Synthetic office','Synthetic supplier','Test truck',12000,12035,'business','manual-odometer',null,'')->>'businessMiles')='35','owner records actual business miles only');
select pg_temp.assert_true((public.record_mileage_trip('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000001','2026-10-15','Synthetic supplier trip','Synthetic office','Synthetic supplier','Test truck',12000,12035,'business','manual-odometer',null,'')->>'businessMiles')='35','same owner key replays exact result');
select pg_temp.assert_true((public.mileage_activity('20000000-0000-4000-8000-000000000001','2026-10-01','2026-10-16',0)->>'businessMiles')='35','mileage report includes one active business trip');
do $assert$begin begin perform public.record_mileage_trip('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000001','2026-10-15','Altered purpose','Synthetic office','Synthetic supplier','Test truck',12000,12035,'business','manual-odometer',null,'');raise exception 'TEST FAILED changed key';exception when others then if sqlerrm='TEST FAILED changed key' then raise;end if;end;end$assert$;
do $assert$begin begin perform public.record_mileage_trip('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000002','84000000-0000-4000-8000-000000000002','2026-10-15','Overlapping supplier trip','Synthetic office','Synthetic supplier','Test truck',12030,12045,'business','manual-odometer',null,'');raise exception 'TEST FAILED business overlap';exception when others then if sqlerrm='TEST FAILED business overlap' then raise;end if;end;end$assert$;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000004","session_id":"10000000-0000-4000-8000-000000000004","aal":"aal1"}',true);
do $assert$begin begin perform public.mileage_activity('20000000-0000-4000-8000-000000000001','2026-10-01','2026-10-16',0);raise exception 'TEST FAILED unauthorized mileage read';exception when insufficient_privilege then null;end;end$assert$;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select pg_temp.assert_true((public.reverse_mileage_trip('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','85000000-0000-4000-8000-000000000001','Synthetic incorrect odometer')->>'reversed')='true','owner reverses but retains trip');
select pg_temp.assert_true((public.reverse_mileage_trip('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','85000000-0000-4000-8000-000000000001','Synthetic incorrect odometer')->>'reversed')='true','same reversal key replays');
select pg_temp.assert_true((public.mileage_activity('20000000-0000-4000-8000-000000000001','2026-10-01','2026-10-16',0)->>'businessMiles')='0','reversed mileage not in business totals');
do $assert$begin begin perform public.reverse_mileage_trip('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','85000000-0000-4000-8000-000000000002','Synthetic incorrect odometer');raise exception 'TEST FAILED alternate reversal';exception when others then if sqlerrm='TEST FAILED alternate reversal' then raise;end if;end;end$assert$;
reset role;
rollback;
